// Zoek het best passende icoon: "checkin.desk.transfer" → "checkin.desk" → "checkin" → standaard
function iconKey(cat, icons = AMENITY_ICONS) {
  let c = cat || "unspecified";
  while (c) {
    if (icons[c]) return c;
    c = c.includes(".") ? c.slice(0, c.lastIndexOf(".")) : null;
  }
  return "unspecified";
}
// Tekent een rond icoon (groepskleur, wit pictogram) op een canvas
const ICON_SIZE = 26, ICON_RATIO = 2, iconCache = {};
function iconCanvas(cat, kind = "amenity") {
  const key = kind + ":" + cat;
  if (iconCache[key]) return iconCache[key];
  const occ = kind === "occupant";
  const px = ICON_SIZE * ICON_RATIO, cv = document.createElement("canvas");
  cv.width = cv.height = px;
  const ctx = cv.getContext("2d"), r = px / 2;
  ctx.beginPath(); ctx.arc(r, r, r - 2 * ICON_RATIO * 0.5, 0, Math.PI * 2);
  ctx.fillStyle = groupColor(occ ? OCC_GROUPS : AMENITY_GROUPS, cat); ctx.fill();
  ctx.lineWidth = 1.5 * ICON_RATIO; ctx.strokeStyle = "#ffffff"; ctx.stroke();
  const inner = px * 0.6, s = inner / 24;
  ctx.setTransform(s, 0, 0, s, (px - inner) / 2, (px - inner) / 2);
  const icons = occ ? OCC_ICONS : AMENITY_ICONS;
  let k = iconKey(cat, icons);
  if (occ && k === "unspecified" && cat && cat !== "unspecified") k = OCC_GROUPS.find(g => g.test(cat)).icon;   // groepsstandaard
  ctx.fillStyle = "#ffffff"; ctx.fill(new Path2D(icons[k]));
  return iconCache[key] = cv;
}
